"""Generated-file banner and locale source comment helpers.

This is the canonical location. codegen/banner.py re-exports
from here so existing emitter imports continue to work.
"""

from __future__ import annotations

import json
import os

_INNER_WIDTH = 62


def make_banner(
    body: list[str],
    line_prefix: str = "# ",
    line_suffix: str = "",
) -> str:
    """Return a 9-line box-frame DO NOT EDIT banner.

    *body* must be exactly 5 lines (content rows between the title
    separator and the bottom border).  Empty strings become blank rows.
    Each output line is wrapped with *line_prefix* / *line_suffix*.
    """
    def _line(content: str) -> str:
        return f"{line_prefix}{content}{line_suffix}\n"

    top    = "\u2554" + "\u2550" * _INNER_WIDTH + "\u2557"
    mid    = "\u2560" + "\u2550" * _INNER_WIDTH + "\u2563"
    bottom = "\u255a" + "\u2550" * _INNER_WIDTH + "\u255d"

    def _row(text: str) -> str:
        return "\u2551" + text.center(_INNER_WIDTH) + "\u2551"

    def _lrow(text: str) -> str:
        return "\u2551" + " " + text.ljust(_INNER_WIDTH - 2) + " \u2551"

    return (
        _line(top)
        + _line(_row("DO NOT EDIT THIS FILE"))
        + _line(mid)
        + "".join(_line(_lrow(row)) for row in body)
        + _line(bottom)
    )


def make_header(generator_path: str, line_prefix: str = "// ", line_suffix: str = "") -> str:
    """Return a 9-line box-frame banner for a codegen-generated file."""
    return make_banner(
        [
            "This file is auto-generated by:",
            f"  {generator_path}",
            "",
            "Changes will be overwritten the next time codegen runs.",
            "Edit the generator or locale JSON instead.",
        ],
        line_prefix=line_prefix,
        line_suffix=line_suffix,
    )


def locale_source_comment(locale_code: str, line_prefix: str = "// ", line_suffix: str = "") -> str:
    """Return a single-line source comment for a locale file."""
    return f"{line_prefix}Source: locales/{locale_code}.json{line_suffix}\n"


LOCALES_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))),
    "locales",
)
# Fields every library shares; each library's own data is under its name.
SHARED_LOCALE_FIELDS = ("code", "name", "pluralRule")


def load_component_locales(component: str) -> list[dict]:
    """Return every locale as one library sees it, sorted by code.

    locales/<code>.json holds the shared fields once and a section per
    library; a library's view is the shared fields plus its own section.
    """
    views = []
    for fname in sorted(os.listdir(LOCALES_DIR)):
        if not fname.endswith(".json"):
            continue
        with open(os.path.join(LOCALES_DIR, fname), encoding="utf-8") as f:
            data = json.load(f)
        view = {k: data[k] for k in SHARED_LOCALE_FIELDS if k in data}
        view.update(data[component])
        views.append(view)
    return views
